const payload = $input.first().json.body || $input.first().json;

const queryText = (payload.query || payload.message || payload.text || '').toString().trim();
const channel = payload.channel || payload.source || 'webchat';
const customerId = payload.customerId || payload.customer_id || payload.email || 'anonymous';
const ticketId = payload.ticketId || payload.ticket_id || null;
const productLine = (payload.product || payload.productLine || 'general').toString().toLowerCase();

if (!queryText) {
  throw new Error('No query text found in incoming payload');
}

return [{
  json: {
    queryText,
    channel,
    customerId,
    ticketId,
    productLine,
    receivedAt: new Date().toISOString()
  }
}];

const searchResponse = $input.first().json;
const query = $('Normalize Incoming Query').first().json;

const matches = searchResponse.matches || [];

// Dedupe by source document, keep highest-scoring chunk per source
const bySource = {};
for (const m of matches) {
  const source = m.metadata?.source || m.metadata?.docTitle || m.id;
  if (!bySource[source] || m.score > bySource[source].score) {
    bySource[source] = m;
  }
}
const ranked = Object.values(bySource).sort((a, b) => b.score - a.score);

const CHAR_BUDGET = 8000;
const sources = [];
let contextBlock = '';
let usedChars = 0;
for (const m of ranked) {
  const text = (m.metadata?.text || '').toString();
  if (!text || usedChars >= CHAR_BUDGET) continue;
  const idx = sources.length + 1;
  sources.push({
    index: idx,
    docTitle: m.metadata?.docTitle || m.metadata?.source || 'Untitled',
    url: m.metadata?.url || null,
    score: m.score
  });
  const chunk = `[${idx}] (${m.metadata?.docTitle || m.metadata?.source || 'source'})\n${text}\n\n`;
  contextBlock += chunk;
  usedChars += chunk.length;
}

const RETRIEVAL_CONFIDENCE_THRESHOLD = 0.75;
const maxScore = ranked.length ? ranked[0].score : 0;
const avgScore = ranked.length ? ranked.slice(0, sources.length).reduce((s, m) => s + m.score, 0) / sources.length : 0;
const retrievalSufficient = maxScore >= RETRIEVAL_CONFIDENCE_THRESHOLD && sources.length > 0;

return [{
  json: {
    ...query,
    contextBlock,
    sources,
    maxScore,
    avgScore,
    retrievalSufficient
  }
}];

const aiResponse = $input.first().json;
const context = $('Process Search Results').first().json;

let result;
try {
  const rawText = aiResponse.content?.[0]?.text || '{}';
  const cleaned = rawText.replace(/```json|```/g, '').trim();
  result = JSON.parse(cleaned);
} catch (e) {
  result = { answer: '', sourcesUsed: [], confidenceScore: 0, needsHumanEscalation: true, escalationReason: 'Unable to parse AI response' };
}

const validSourceIndices = new Set((context.sources || []).map(s => s.index));
const citedSources = result.sourcesUsed || [];
const hallucinatedCitations = citedSources.some(i => !validSourceIndices.has(i));

const ESCALATION_KEYWORDS = ['refund', 'cancel my account', 'cancel subscription', 'chargeback', 'legal', 'lawsuit', 'unauthorized charge', 'data breach'];
const lowerQuery = (context.queryText || '').toLowerCase();
const matchedKeyword = ESCALATION_KEYWORDS.find(k => lowerQuery.includes(k));

const MIN_CONFIDENCE_FOR_AUTOREPLY = 70;
const needsHumanEscalation = Boolean(result.needsHumanEscalation)
  || hallucinatedCitations
  || (result.confidenceScore ?? 0) < MIN_CONFIDENCE_FOR_AUTOREPLY
  || Boolean(matchedKeyword)
  || citedSources.length === 0;

return [{
  json: {
    ...context,
    generatedAnswer: result.answer || '',
    sourcesUsed: citedSources,
    confidenceScore: result.confidenceScore ?? 0,
    hallucinatedCitations,
    matchedEscalationKeyword: matchedKeyword || null,
    needsHumanEscalation,
    escalationReason: result.escalationReason || ''
  }
}];

const item = $input.first().json;

const reasons = [];
if (item.retrievalSufficient === false) reasons.push('No sufficiently relevant documentation was retrieved for this question.');
if (item.hallucinatedCitations) reasons.push('AI cited a source that was not in the retrieved context.');
if ((item.confidenceScore ?? 0) > 0 && item.confidenceScore < 70) reasons.push(`AI confidence too low (${item.confidenceScore}%).`);
if (item.matchedEscalationKeyword) reasons.push(`Query matched a sensitive-topic keyword: "${item.matchedEscalationKeyword}".`);
if (item.escalationReason) reasons.push(item.escalationReason);
if (reasons.length === 0) reasons.push('Did not meet auto-reply criteria.');

return [{
  json: {
    ...item,
    path: 'escalation',
    resolutionStatus: 'Escalated to Human Agent',
    escalationReasons: reasons,
    draftAnswer: item.generatedAnswer || null,
    resolvedAt: new Date().toISOString()
  }
}];
